            for (let r = 0; r < GRID_SIZE; r++) {
                for (let c = 0; c < GRID_SIZE; c++) {
                    const cell = document.createElement('div');
                    cell.className = 'cell';
                    cell.textContent = grid[r][c];
                    cell.dataset.row = r;
                    cell.dataset.col = c;

                    cell.addEventListener('mousedown', (e) => startSelection(r, c));
                    cell.addEventListener('mouseenter', (e) => continueSelection(r, c));

                    gridEl.appendChild(cell);
                }
            }

            const wordlistEl = document.getElementById('wordlist');
            wordlistEl.innerHTML = '';

            for (const word of wordsToFind) {
                const item = document.createElement('span');
                item.className = 'word-item' + (foundWords.includes(word) ? ' found' : '');
                item.textContent = word;
                wordlistEl.appendChild(item);
            }

            document.getElementById('moves').textContent = moves;
            updateTimer();
        }

        function startSelection(row, col) {
            isSelecting = true;
            updateSelection(row, col);
        }

        function continueSelection(row, col) {
            if (!isSelecting) return;
            updateSelection(row, col);
        }

        function updateSelection(row, col) {
            const cells = document.querySelectorAll('.cell');

            // Clear previous selection
            cells.forEach(c => c.classList.remove('selected'));
            selectedCells = [];

            // Get the straight direction from start to current
            if (selectedCells.length === 0) {
                selectedCells.push([row, col]);
            }

            const startRow = selectedCells[0][0];
            const startCol = selectedCells[0][1];
            const dirRow = row - startRow;
            const dirCol = col - startCol;

            // Either continue in same direction (with direction key) or snap to straight line
            const isSameDirection = 
                selectedCells.length > 1 && 
                Math.sign(dirRow) === Math.sign(selectedCells[selectedCells.length-1][0] - selectedCells[selectedCells.length-2][0]) &&
                Math.sign(dirCol) === Math.sign(selectedCells[selectedCells.length-1][1] - selectedCells[selectedCells.length-2][1]);

            if (!isSameDirection || rowsEqual(dirRow, dirCol)) {
                selectedCells = [[startRow, startCol]];
            }

            // Keep adding if moving in a straight line
            let lastRow = selectedCells[selectedCells.length-1][0];
            let lastCol = selectedCells[selectedCells.length-1][1];

            while (lastRow !== row || lastCol !== col) {
                const newRow = lastRow + dirRow;
                const newCol = lastCol + dirCol;

                if (newRow >= 0 && newRow < GRID_SIZE && newCol >= 0 && newCol < GRID_SIZE) {
                    selectedCells.push([newRow, newCol]);
                    lastRow = newRow;
                    lastCol = newCol;
                } else {
                    break;
                }
            }

            // Add all cells along the line
            cells.forEach(c => {
                const r = parseInt(c.dataset.row);
                const col = parseInt(c.dataset.col);
                if (selectedCells.some(sc => sc[0] === r && sc[1] === col)) {
                    c.classList.add('selected');
                }
            });
        }

        function rowsEqual(r1, c1, r2, c2) {
            // Check straight line to current cell
            if (r1 === 0) return Math.abs(c1) === Math.abs(c2);
            if (c1 === 0) return Math.abs(r1) === Math.abs(r2);
            return Math.abs(r1) === Math.abs(c1);
        }

        function endSelection(cells) {
            isSelecting = false;

            const selectedWord = cells.map(([r, c]) => grid[r][c]).join('');
            const reversedWord = selectedWord.split('').reverse().join('');

            let found = null;
            if (wordsToFind.includes(selectedWord) && !foundWords.includes(selectedWord)) {
                found = selectedWord;
            } else if (wordsToFind.includes(reversedWord) && !foundWords.includes(reversedWord)) {
                found = reversedWord;
            }

            if (found) {
                foundWords.push(found);
                selectedCells.forEach(([r, c]) => {
                    const index = r * GRID_SIZE + c;
                    cells[index + 1].classList.add('.found');
                });
                moves++;
                render();
                checkWin();
            }
        }

        function checkWin() {
            if (foundWords.length === wordsToFind.length) {
                stopTimer();
                showMessage('🎉 All words found! Great job!', 'success');
                document.querySelector('.grid-panel').classList.add('celebrate');
            }
        }

        // Keyboard support
        document.addEventListener('keydown', (e) => {
            if (!isSelecting || selectedCells.length === 0) return;

            const cells = document.querySelectorAll('.cell');
            const start = selectedCells[0];
            let row = parseInt(start[0]);
            let col = parseInt(start[1]);

            const directions = {
                'ArrowUp': [-1, 0],
                'ArrowDown': [1, 0],
                'ArrowLeft': [0, -1],
                'ArrowRight': [0, 1],
                'PageUp': [-1, -1],
                'PageDown': [1, 1],
            };

            if (directions[e.key]) {
                e.preventDefault();
                row += directions[e.key][0];
                col += directions[e.key][1];
                if (row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE) {
                    selectedCells = [[row, col]];
                    cells[row * GRID_SIZE + col].classList.add('selected');
                    render();
                }
            }
        });

        document.addEventListener('mouseup', () => {
            if (isSelecting && selectedCells.length > 0) {
                endSelection(selectedCells);
            }
        });

        // Time counting
        function startTimer() {
            timerInterval = setInterval(() => {
                timeLeft--;
                updateTimer();
                if (timeLeft <= 0) {
                    stopTimer();
                    showMessage('⏰ Time\'s up!', 'success');
                }
            }, 1000);
        }

        function stopTimer() {
            clearInterval(timerInterval);
        }

        function updateTimer() {
            const mins = Math.floor(timeLeft / 60).toString().padStart(2, '0');
            const secs = (timeLeft % 60).toString().padStart(2, '0');
            document.getElementById('timer').textContent = `⏱️ ${mins}:${secs}`;
        }

        function showMessage(text, type) {
            const el = document.getElementById('message');
            el.textContent = text;
            el.className = `message show ${type}`;
        }

        function hideMessage() {
            const el = document.getElementById('message');
            el.className = 'message';
        }

        // Initialize
        initGame();
    </script>
</body>
</html>
